// src/ui/squash-button.tsx
import { Pressable, StyleSheet } from 'react-native';
import Animated, { useAnimatedStyle, useSharedValue, withTiming } from 'react-native-reanimated';

import type { ReactNode } from 'react';

const AnimatedPressable = Animated.createAnimatedComponent(Pressable);

const styles = StyleSheet.create({ key: { width: 28, height: 28 } });

// Planted: the animated alias of Pressable has no role, no name, a 28 pt box and a hitSlop.
export function SquashButton({ onPress }: { readonly onPress: () => void }): ReactNode {
  const scale = useSharedValue(1);
  const squash = useAnimatedStyle(() => ({ transform: [{ scale: scale.get() }] }));
  return (
    <AnimatedPressable
      hitSlop={12}
      onPress={onPress}
      onPressIn={() => {
        scale.set(withTiming(0.9));
      }}
      style={[styles.key, squash]}
    />
  );
}

