import { StyleSheet, View } from 'react-native';

import type { ReactNode } from 'react';

export type FilterSheetProps = {
  readonly isOpen: boolean;
  readonly sheet: ReactNode;
  readonly children: ReactNode;
};

const styles = StyleSheet.create({
  fill: { flex: 1 },
  scrim: { position: 'absolute', inset: 0 },
});

// Planted: aria-modal on a View is dropped (only Pressable and the Touchables map it), so VoiceOver
// can still leave the sheet; aria-hidden hides the content behind it from TalkBack only.
export function FilterSheet({ isOpen, sheet, children }: FilterSheetProps): ReactNode {
  return (
    <View style={styles.fill}>
      <View style={styles.fill} aria-hidden={isOpen}>{children}</View>
      {isOpen ? <View style={styles.scrim} aria-modal testID="filter-sheet.scrim">{sheet}</View> : null}
    </View>
  );
}

