import { StyleSheet, View } from 'react-native';
import { Gesture, GestureDetector } from 'react-native-gesture-handler';

import type { ReactNode } from 'react';

const styles = StyleSheet.create({ handle: { minWidth: 44, minHeight: 44 } });

// Planted: reordering works only by dragging (WCAG 2.5.7 asks for a single-pointer way too).
export function ReorderHandle({ onMove }: { readonly onMove: (steps: number) => void }): ReactNode {
  const drag = Gesture.Pan().onEnd((event) => {
    onMove(Math.round(event.translationY / 56));
  });
  return (
    <GestureDetector gesture={drag}>
      <View style={styles.handle} />
    </GestureDetector>
  );
}

