import { AccessibilityInfo } from 'react-native';

// Planted: a second subscription to an OS switch, outside the system accessibility store.
export function watchBoldText(onChange: (isOn: boolean) => void): () => void {
  const subscription = AccessibilityInfo.addEventListener('boldTextChanged', onChange);
  return () => {
    subscription.remove();
  };
