// src/ui/swipe-row.tsx
import { Pressable, StyleSheet } from 'react-native';
import ReanimatedSwipeable from 'react-native-gesture-handler/ReanimatedSwipeable';

import type { ReactNode } from 'react';
import type { AccessibilityActionEvent } from 'react-native';

export type SwipeAction = {
  readonly name: string;
  /** Translated: what the VoiceOver Actions rotor and the TalkBack actions menu speak. */
  readonly label: string;
  readonly onRun: () => void;
};

export type SwipeRowProps = {
  readonly openLabel: string;
  readonly onOpen: () => void;
  readonly testID: string;
  /** Every action the swipe reveals, also offered as a named accessibility action on the opener. */
  readonly actions: readonly SwipeAction[];
  readonly renderRightActions: () => ReactNode;
  readonly children: ReactNode;
};

const styles = StyleSheet.create({ row: { minHeight: 56 } });

// The shared row declares the actions itself, so a feature row built on it cannot leave them out.
export function SwipeRow(props: SwipeRowProps): ReactNode {
  const handleAction = (event: AccessibilityActionEvent): void => {
    props.actions.find((action) => action.name === event.nativeEvent.actionName)?.onRun();
  };
  return (
    <ReanimatedSwipeable renderRightActions={props.renderRightActions}>
      <Pressable
        accessibilityRole="button"
        accessibilityLabel={props.openLabel}
        accessibilityActions={props.actions.map(({ name, label }) => ({ name, label }))}
        onAccessibilityAction={handleAction}
        onPress={props.onOpen}
        style={styles.row}
        testID={props.testID}
      >
        {props.children}
      </Pressable>
    </ReanimatedSwipeable>
  );
}

