import { StyleSheet, View } from 'react-native';

import type { ReactNode } from 'react';

export type SortSheetProps = {
  readonly isOpen: boolean;
  readonly sheet: ReactNode;
  readonly children: ReactNode;
};

const styles = StyleSheet.create({
  fill: { flex: 1 },
  scrim: { position: 'absolute', inset: 0 },
});

// A web-enabled app keeps both flags on the scrim: accessibilityViewIsModal for VoiceOver (React
// Native drops aria-modal on a View) and aria-modal for the browser (react-native-web maps it, not
// the iOS flag). aria-hidden on the sibling hides the screen behind from TalkBack.
export function SortSheet({ isOpen, sheet, children }: SortSheetProps): ReactNode {
  return (
    <View style={styles.fill}>
      <View style={styles.fill} aria-hidden={isOpen}>{children}</View>
      {isOpen ? (
        <View style={styles.scrim} accessibilityViewIsModal aria-modal testID="sort-sheet.scrim">
          {sheet}
        </View>
      ) : null}
    </View>
  );
}
